// Service worker for the Takamul site (generated by tools/build.py — edit tools/sw.template.js).
// HTML: network-first (fresh content when online, cached copy offline).
// CSS/JS/images/data: stale-while-revalidate. /api/* is never cached.
const VERSION = '41e9a967ac9a';
const CACHE = 'takamul-' + VERSION;
const PRECACHE = ["./", "./index.html", "./manifest.webmanifest", "./css/style.css", "./css/pages.css", "./css/chat-plus.css", "./css/palette.css", "./css/globe.css", "./js/main.js", "./js/chat.js", "./js/palette.js", "./js/cursor.js", "./js/pwa.js", "./data/kb.js", "./assets/logo.png", "./assets/icons/icon-192.png", "./assets/img/istanbul.jpg", "./about.html", "./dashboard.html", "./expansion.html", "./faq.html", "./governance.html", "./initiatives.html", "./join.html", "./support.html"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('takamul-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || url.pathname.startsWith('/api/')) return;
  const isPage = req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html');
  if (isPage) {
    e.respondWith(fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return res;
    }).catch(() => caches.match(req, { ignoreSearch: true })
      .then(r => r || caches.match(url.pathname.replace(/[^/]*$/, '') + 'index.html'))
      .then(r => r || caches.match('./index.html'))));
    return;
  }
  e.respondWith(caches.match(req).then(hit => {
    const net = fetch(req).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      return res;
    }).catch(() => hit);
    return hit || net;
  }));
});
